            <rect x="148" y={targetY(t) - 8} width="44" height="16" rx="4" fill={t === 'Sign up' ? '#059669' : '#94a3b8'} fillOpacity="0.2" stroke={t === 'Sign up' ? '#059669' : '#94a3b8'} strokeWidth="1" />
